'use strict';
const WHATSAPP='5521971146102';
const pillars=[{name:'Leads qualificados',short:'Captação e qualificação'},{name:'Site, Google e IAs',short:'Presença digital'},{name:'Automações e atendimento',short:'Atendimento e acompanhamento'}];
const questions=window.AmorimQuestions;
const app=document.getElementById('app');
const state={step:-1,answers:[],lead:{name:'',business:'',city:'',phone:'',email:'',contact_consent:false}};
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const rotatingPlatforms=()=>`<span class="platform-rotation" role="img" aria-label="ChatGPT, Gemini ou Google"><span aria-hidden="true">ChatGPT</span><span aria-hidden="true">Gemini</span><span aria-hidden="true">Google</span></span>`;
const metrics=window.AmorimMetrics;
const arrow='<span class="arrow" aria-hidden="true">↗</span>';
function render(html){app.innerHTML=html;window.scrollTo({top:0,behavior:'instant'});const h=app.querySelector('h1');if(h){h.tabIndex=-1;h.focus({preventScroll:true});}}
function intro(){state.step=-1;render(`
 <section class="hero"><div><p class="eyebrow">DIAGNÓSTICO GRATUITO · IMOBILIÁRIAS</p>
 <h1>Seu próximo cliente perguntou ao <em>${rotatingPlatforms()}</em> onde comprar um imóvel.<span class="last">Ele indicou a sua imobiliária?</span></h1>
 <p class="lead">Quem procura um imóvel precisa encontrar você. Descubra como estão sua captação de <strong>leads qualificados</strong>, sua presença no Google e nas IAs e seu atendimento até a visita.</p>
 <button class="btn" data-start>Fazer o diagnóstico ${arrow}</button><p class="note"><span>✓</span> 11 perguntas · cerca de 3 minutos · resultado na hora</p></div>
 <div class="scene"><div class="architecture" aria-hidden="true"><div class="building"></div><div class="building two"></div></div><span class="scene-label">SEU PRÓXIMO CLIENTE ESTÁ BUSCANDO</span>
 <div class="chat-card"><div class="chat-top"><b class="chat-platform">✳ ${rotatingPlatforms()}</b> <span>SIMULAÇÃO ILUSTRATIVA</span></div><div class="chat-content"><div class="bubble">Quais imobiliárias podem me ajudar a comprar um apartamento na minha cidade?</div><div class="chat-answer"><p>Você pode começar sua pesquisa por estas opções:</p>${['Imobiliária Horizonte','Morada Imóveis','Casa Nova Negócios'].map((n,i)=>`<div class="listing"><span class="num">0${i+1}</span><div><b>${n}</b><small>Nome fictício para esta simulação</small></div></div>`).join('')}<div class="missing"><b>E a sua imobiliária?</b><span>Ela seria lembrada?</span></div></div></div></div><div class="floating">Ser encontrado é o começo. <b>Gerar visitas é o próximo passo.</b></div></div></section>
 <section class="pillars-strip" aria-label="O que vamos avaliar">${pillars.map((p,i)=>`<div class="strip-item"><span class="index">0${i+1}</span><div><b>${p.name}</b><small>${['Interessados com perfil para sua carteira','Sua imobiliária presente na busca','Da primeira mensagem ao acompanhamento'][i]}</small></div></div>`).join('')}</section>
 <section class="how"><div><p class="eyebrow">UM OLHAR PARA O CAMINHO INTEIRO</p><h2>Mais do que receber contatos.<br>É criar oportunidades.</h2><p>Uma boa captação precisa de uma presença digital clara e de um atendimento preparado. O diagnóstico ajuda a identificar onde começar.</p></div><div class="how-list"><details open><summary>01 · Os interessados têm o perfil que você busca?</summary><p>Avaliamos direcionamento, qualificação e acompanhamento dos canais que geram visitas.</p></details><details><summary>02 · Sua imobiliária é fácil de encontrar?</summary><p>Olhamos para a organização do site e sua rotina de presença no Google e nas ferramentas de IA.</p></details><details><summary>03 · O atendimento faz a conversa avançar?</summary><p>Identificamos oportunidades no tempo de resposta, no atendimento fora do horário e nas retomadas.</p></details></div></section>
 <section class="bottom-cta"><div><h3>Por onde sua imobiliária deve começar?</h3><p>Responda às perguntas e receba suas prioridades de melhoria.</p></div><button class="btn" data-start>Descobrir minhas prioridades ${arrow}</button></section>`);app.querySelectorAll('[data-start]').forEach(b=>b.onclick=()=>{metrics.track('start',{},true);question(0)});}
function question(i){metrics.track('question',{step:i},true);state.step=i;const q=questions[i],sel=state.answers[i];render(`<section class="step-wrap"><div class="progress" role="progressbar" aria-label="Progresso do diagnóstico" aria-valuemin="0" aria-valuemax="11" aria-valuenow="${i+1}"><i style="width:${(i+1)/11*100}%"></i></div><div class="step-meta"><span>${q.p<0?'Sobre sua imobiliária':pillars[q.p].name}</span><span>${String(i+1).padStart(2,'0')} / 11</span></div><h1 id="question-title">${esc(q.q)}</h1>${q.hint?`<p class="hint">${esc(q.hint)}</p>`:''}<div class="options" role="${q.multi?'group':'radiogroup'}" aria-labelledby="question-title">${q.o.map((o,k)=>`<button class="option" role="${q.multi?'checkbox':'radio'}" aria-checked="${q.multi?(sel||[]).includes(k):sel===k}" data-option="${k}"><kbd aria-hidden="true">${k+1}</kbd><span>${esc(o)}</span></button>`).join('')}</div><div class="step-nav"><button class="back" id="back">← Voltar</button><button class="btn" id="next" ${q.multi?!(sel||[]).length?'disabled':'':sel===undefined?'disabled':''}>${i===10?'Ver diagnóstico':'Continuar'} <span aria-hidden="true">→</span></button></div><p class="step-help">${q.multi?'Selecione as opções que se aplicam.':'Escolha uma opção para continuar.'} Registramos o progresso para melhorar o diagnóstico. Seus contatos são salvos ao enviar o formulário final.</p></section>`);app.querySelectorAll('[data-option]').forEach(b=>b.onclick=()=>{const k=Number(b.dataset.option);if(q.multi){let s=[...(state.answers[i]||[])];s=s.includes(k)?s.filter(x=>x!==k):[...s,k];if(k===6&&s.includes(6))s=[6];else s=s.filter(x=>x!==6);state.answers[i]=s;}else state.answers[i]=k;app.querySelectorAll('[data-option]').forEach(el=>el.setAttribute('aria-checked',String(q.multi?state.answers[i].includes(Number(el.dataset.option)):state.answers[i]===Number(el.dataset.option))));document.getElementById('next').disabled=q.multi?!state.answers[i].length:false;});document.getElementById('back').onclick=()=>i?question(i-1):intro();document.getElementById('next').onclick=()=>{metrics.track('answer',{step:i,answer:state.answers[i]});i<10?question(i+1):leadForm();};}
function leadForm(){state.step=11;metrics.track('form',{step:11},true);render(`<section class="step-wrap"><div class="progress"><i style="width:100%"></i></div><p class="eyebrow">SEU DIAGNÓSTICO ESTÁ PRONTO</p><h1>Vamos dar um nome ao seu próximo passo.</h1><p class="hint">Preencha seus dados para salvar seu diagnóstico e consultar suas prioridades.</p><form id="lead-form"><div class="form-grid"><label>Seu nome<input name="name" autocomplete="given-name" maxlength="80" required value="${esc(state.lead.name)}" placeholder="Como podemos chamar você?"></label><label>Nome da imobiliária<input name="business" autocomplete="organization" maxlength="120" required value="${esc(state.lead.business)}" placeholder="Sua imobiliária"></label><label>Cidade ou região<input name="city" maxlength="100" required value="${esc(state.lead.city)}" placeholder="Ex.: Niterói, RJ"></label><label>Seu WhatsApp com DDD<input name="phone" type="tel" autocomplete="tel" maxlength="25" required value="${esc(state.lead.phone)}" placeholder="(21) 99999-9999"></label><label>E-mail (opcional)<input name="email" type="email" autocomplete="email" maxlength="120" value="${esc(state.lead.email)}" placeholder="voce@imobiliaria.com.br"></label></div><label class="consent"><input name="contact_consent" type="checkbox" ${state.lead.contact_consent?'checked':''}><span>Quero receber contato da Amorim Soluções Digitais sobre as oportunidades identificadas.</span></label><p class="privacy-note">Ao clicar em “Ver meu diagnóstico”, seus dados, respostas e resultado serão salvos pela Amorim Soluções Digitais para registrar esta avaliação. O contato comercial depende da opção acima. Consulte “Privacidade” no rodapé.</p><p class="error" id="form-error" role="alert"></p><div class="step-nav"><button type="button" class="back" id="back">← Voltar</button><button class="btn" type="submit">Ver meu diagnóstico ${arrow}</button></div></form></section>`);const form=document.getElementById('lead-form');const sync=()=>{for(const k of Object.keys(state.lead))state.lead[k]=k==='contact_consent'?form.elements[k].checked:form.elements[k].value.trim();};form.oninput=sync;form.onsubmit=async e=>{e.preventDefault();sync();const phone=state.lead.phone.replace(/\D/g,'');if(!state.lead.name||!state.lead.business||!state.lead.city||phone.length<10||phone.length>13){document.getElementById('form-error').textContent='Preencha os campos e informe um WhatsApp válido com DDD.';return;}const button=form.querySelector('[type=submit]');button.disabled=true;button.textContent='Salvando diagnóstico…';const ok=await metrics.track('result',{answers:state.answers,lead:{...state.lead}},true);if(!ok){document.getElementById('form-error').textContent='Não foi possível salvar agora. Confira sua conexão e tente novamente. Suas respostas continuam nesta página.';button.disabled=false;button.innerHTML='Tentar salvar novamente →';return;}result();};document.getElementById('back').onclick=()=>question(10);}
function calculate(answers){const points=pillars.map((_,p)=>questions.reduce((sum,q,i)=>sum+(q.p===p?3-answers[i]:0),0));const scores=points.map(n=>Math.round(n/9*100));const total=Math.round(points.reduce((a,b)=>a+b,0)/27*100);const findings=questions.map((q,i)=>({...q,i,value:q.p>=0?3-answers[i]:3})).filter(q=>q.p>=0&&q.value<=1).sort((a,b)=>a.value-b.value||a.p-b.p||a.i-b.i).slice(0,3);return{scores,total,findings};}
function summary(s){return `Olá, Amorim Soluções Digitais! Fiz o diagnóstico imobiliário.\nSou ${state.lead.name}, da ${state.lead.business}, em ${state.lead.city}.\nMeu índice de estrutura comercial foi ${s.total}/100.\n${pillars.map((p,i)=>`${p.name}: ${s.scores[i]}/100`).join('\n')}\n${s.findings.length?'Prioridades: '+s.findings.map(f=>f.issue).join('; ')+'.':'Quero validar meus processos e identificar oportunidades de melhoria.'}\nQuero conversar sobre leads qualificados, site otimizado para Google e IAs e automações de atendimento.`;}
function result(){state.step=12;const s=calculate(state.answers),low=s.scores.indexOf(Math.min(...s.scores)),title=s.total<40?'Há etapas importantes para organizar.':s.total<70?'Sua operação tem uma base. Vamos conectar os pontos.':'Sua imobiliária tem uma boa estrutura.';const guidance=s.total>=70?'O próximo passo é validar o processo com indicadores reais de qualidade, visitas e atendimento.':`Pelas suas respostas, ${pillars[low].name.toLowerCase()} é o ponto que mais merece atenção agora.`;const prompt=`Quais imobiliárias podem me ajudar a comprar um imóvel em ${state.lead.city}? Mostre as fontes usadas para indicar cada opção.`;render(`<section class="results"><div class="res-head"><div><p class="eyebrow">DIAGNÓSTICO · ${esc(state.lead.business)}</p><h1>${title}</h1><p>${esc(state.lead.name)}, este é um retrato dos processos que você descreveu. ${guidance}</p></div><div class="score" style="--score:${s.total}" aria-label="Índice ${s.total} de 100">${s.total}<small>DE 100</small></div></div><p class="section-note">Índice de estrutura comercial baseado nas suas respostas. Não mede vendas perdidas nem comprova posição no Google ou nas IAs.</p><div class="scores">${pillars.map((p,i)=>`<div class="score-card"><b>${p.name}</b><strong>${s.scores[i]}<small style="font:12px var(--sans)">/100</small></strong><div class="meter"><i style="width:${s.scores[i]}%"></i></div></div>`).join('')}</div><section class="result-section"><p class="eyebrow">SEU PLANO DE PARTIDA</p><h2>${s.findings.length?'Onde começar a melhorar':'Como avançar a partir de uma boa base'}</h2>${s.findings.length?s.findings.map((f,i)=>`<article class="find"><span>0${i+1}</span><div><h3>${esc(f.issue)}</h3><p>${esc(f.why)}</p><p class="action"><strong>Próximo passo:</strong> ${esc(f.action)}</p></div></article>`).join(''):`<article class="find"><span>01</span><div><h3>Confira se a prática confirma o processo</h3><p>Compare a qualidade dos contatos e as visitas por canal, revise o conteúdo e a indexação do site e acompanhe tempo de resposta e retornos.</p><p class="action">A automação pode apoiar tarefas repetitivas depois que as oportunidades forem identificadas.</p></div></article>`}</section><section class="result-section"><h2>Da situação atual ao próximo passo</h2><p class="section-note">Possibilidades para um plano de trabalho com a Amorim Soluções Digitais. O escopo depende da avaliação da sua operação.</p><table class="compare"><thead><tr><th>Hoje, pelas suas respostas</th><th>O que podemos estruturar</th></tr></thead><tbody>${(s.findings.length?s.findings:[{today:'Processos já estruturados',after:'Validação por indicadores e melhoria contínua'}]).map(f=>`<tr><td>${esc(f.today)}</td><td>${esc(f.after)}</td></tr>`).join('')}</tbody></table></section><section class="ai-test"><h3>E a pergunta da abertura?</h3><p>Faça um teste por conta própria. Os resultados variam por ferramenta, consulta, local e momento; uma busca isolada não representa uma auditoria.</p><div class="prompt">${esc(prompt)}</div><div class="ai-actions"><a class="btn secondary" href="https://chatgpt.com/?q=${encodeURIComponent(prompt)}" target="_blank" rel="noopener noreferrer">Testar no ChatGPT ↗</a><a class="btn secondary" href="https://www.google.com/search?q=${encodeURIComponent('imobiliária em '+state.lead.city)}" target="_blank" rel="noopener noreferrer">Pesquisar no Google ↗</a></div></section><section class="result-cta"><p class="eyebrow" style="justify-content:center;color:var(--sand)">AMORIM SOLUÇÕES DIGITAIS</p><h2>Vamos criar um caminho para atrair interessados com mais perfil?</h2><p>Leads qualificados primeiro. Site e presença digital para ser encontrado.<br>Automações para dar continuidade a cada oportunidade.</p><a id="whatsapp" class="btn" href="https://wa.me/${WHATSAPP}?text=${encodeURIComponent(summary(s))}" target="_blank" rel="noopener noreferrer">Conversar sobre meu diagnóstico ${arrow}</a><small>Seu resumo será aberto no WhatsApp. Você decide quando enviar.</small></section><div class="result-tools"><button class="back" id="download">↓ Baixar meu diagnóstico</button><button class="back" id="restart">↻ Refazer diagnóstico</button></div><p id="result-status" class="toast" role="status"></p></section>`);document.getElementById('restart').onclick=()=>{state.answers=[];metrics.newRun();intro();};document.getElementById('download').onclick=()=>{metrics.track('download');const text=`DIAGNÓSTICO IMOBILIÁRIO | AMORIM SOLUÇÕES DIGITAIS\n\n${summary(s)}\n\nPRÓXIMOS PASSOS\n${s.findings.map(f=>f.issue+'\n'+f.action).join('\n\n')}\n\nRESPOSTAS\n${questions.map((q,i)=>q.q+'\n'+(q.multi?state.answers[i].map(k=>q.o[k]).join(', '):q.o[state.answers[i]])).join('\n\n')}\n\nÍndice indicativo baseado em autoavaliação. Não representa auditoria, previsão de vendas ou garantia de posicionamento.`;const url=URL.createObjectURL(new Blob([text],{type:'text/plain;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='diagnostico-imobiliario-amorim.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);document.getElementById('result-status').textContent='Seu diagnóstico foi preparado para download.';};}
document.getElementById('year').textContent=new Date().getFullYear();
const privacy=document.getElementById('privacy-dialog');document.getElementById('privacy').onclick=()=>privacy.showModal();privacy.querySelector('.close').onclick=()=>privacy.close();privacy.onclick=e=>{if(e.target===privacy){const r=privacy.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)privacy.close();}};
document.addEventListener('click',e=>{const a=e.target.closest?.('a[href]');if(!a)return;if(a.id==='whatsapp')metrics.track('whatsapp');else if(a.href.startsWith('https://chatgpt.com/'))metrics.track('chatgpt');else if(a.href.startsWith('https://www.google.com/search'))metrics.track('google');});
intro();
